async function cdqLoadPdfRecord(id){
  let rec=await cdqEnsurePdf(id,false);
  const pending=(await cdqV19QueueGet()).find(a=>a.kind==='pdf-import'&&a.targetId===id);
  if(pending)rec=Object.assign({},rec,{blob:new Blob([cdqV2112Base64ToBytes(pending.data)],{type:'application/pdf'})});
  // Les gros PDF haute qualité ne sont plus entièrement réécrits avant ouverture.
  // PDF-Lib pouvait bloquer Android plusieurs dizaines de secondes sans retour.
  if(rec&&rec.blob instanceof Blob&&rec.blob.size<=8*1024*1024){
    rec=await cdqPersonnaliserRecordTechnicienPdf(rec);
  }
  try{if(!pending)await cdqV19PutRecord('document-pdf',id,rec);}catch(e){}
  return rec;
}

